INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(10701, '2 Chronicles 13:9', '2 Chronicles', 13, 9, '&nbsp;تاسو د هارون اولاد يعنې د مالِک خُدائ اِمامان او ليويان هم وشړل. او هم هغه شان اِمامان مو مقرر کړل لکه څنګه چې د غېرو قومونو خلق مقرروى. هر څوک چې خپل ځان وقف کولو دپاره د يو غوَيى سره يا د اووۀ ګډانو سره راشى نو هغه د دې معبودانو اِمام جوړېدے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10702, '2 Chronicles 13:10', '2 Chronicles', 13, 10, '&nbsp;خو مونږ تر اوسه پورې د مالِک خُدائ زمونږ د خُدائ پاک خِدمت کوُو او مونږ هغه نۀ دے پرېښودلے. د هارون د اولاد اِمامان خپلې ذمه وارۍ تر سره کوى او ليويان د هغوئ مدد کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10703, '2 Chronicles 13:11', '2 Chronicles', 13, 11, '&nbsp;هر سحر او هر ماښام هغوئ هغۀ ته خوشبوئى او پوره سوزېدونکې نذرانې پېش کوى. هغوئ په هغه مېز باندې د روټۍ نذرانې پېش کوى کوم چې پاک دے او هره شپه هغوئ د سرو زرو په ډيوټ باندې ډيوې بلوى. مونږ د مالِک خُدائ د خپل خُدائ پاک په اصُولو باندې عمل کوُو، خو تاسو هغه پرېښے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10704, '2 Chronicles 13:12', '2 Chronicles', 13, 12, '&nbsp;خُدائ پاک په خپله زمونږ مشر دے او اِمامان د بيګلو سره ولاړ دى، چې د دې د غږولو دپاره تيار دى چې مونږ ستاسو خِلاف د جنګ دپاره راوغواړى. اے اِسرائيليانو، د مالِک خُدائ خِلاف جنګ مۀ کوئ، کوم چې ستاسو د پلار نيکۀ خُدائ پاک دے. تاسو دا جنګ نۀ شئ ګټلے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10705, '2 Chronicles 13:13', '2 Chronicles', 13, 13, '&nbsp;په دې دوران کښې يربعام خپل څۀ فوجيان پټ ځائ ته د دې دپاره لېږلى وُو چې د يهوداه لښکر د شا د طرف نه ګېر کړى، چې هغه نور ورباندې د مخې نه راغلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10706, '2 Chronicles 13:14', '2 Chronicles', 13, 14, '&nbsp;د يهوداه خلقو ګېرچاپېره وکتل او پته ورته ولګېده چې هغوئ ګېر شوى دى. نو هغوئ مالِک خُدائ ته د مدد دپاره چغه کړه او اِمامانو بيګلې وغږولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10707, '2 Chronicles 13:15', '2 Chronicles', 13, 15, '&nbsp;د يهوداه خلقو يوه درنه چغه ووهله او ابياه هغوئ روان کړل او هغوئ حمله وکړه، خُدائ پاک يربعام او د اِسرائيلو لښکر له شکست ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10708, '2 Chronicles 13:16', '2 Chronicles', 13, 16, '&nbsp;اِسرائيليان د يهوداه د خلقو نه وتښتېدل او خُدائ پاک د يهوداه خلق په هغوئ باندې زورَور کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10709, '2 Chronicles 13:17', '2 Chronicles', 13, 17, '&nbsp;ابياه او د هغۀ لښکر اِسرائيليانو له يو خراب شکست ورکړو او د اِسرائيليانو پينځۀ لاکه تکړه فوجيان ووژلے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10710, '2 Chronicles 13:18', '2 Chronicles', 13, 18, '&nbsp;نو د يهوداه خلقو په اِسرائيلو باندې ځکه فتح وموندله، چې هغوئ په مالِک خُدائ د هغوئ د پلار نيکۀ په خُدائ پاک باندې ايمان لرلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10711, '2 Chronicles 13:19', '2 Chronicles', 13, 19, '&nbsp;ابياه د يربعام په لښکر پسې وو او د هغۀ څۀ ښارونه يې قبضه کړل، بيت‌ايل، يسانه او عِفرون او د دې ټولو ښارونو سره نزدې کلى يې قبضه کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10712, '2 Chronicles 13:20', '2 Chronicles', 13, 20, '&nbsp;يربعام ته د ابياه د بادشاهۍ په دوران کښې هيڅکله دوباره طاقت مِلاو نۀ شو. او په آخر کښې مالِک خُدائ هغه ووهلو او هغه مړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10713, '2 Chronicles 13:21', '2 Chronicles', 13, 21, '&nbsp;خو ابياه نور هم تکړه شو. د هغۀ څوارلس ښځې وې او د دوويشتو زامنو او د شپاړسو لوڼو پلار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10714, '2 Chronicles 13:22', '2 Chronicles', 13, 22, '&nbsp;د ابياه باقى نور تاريخ يعنې چې هغۀ څۀ کړى او وئيلى وُو، هغه د عدو پېغمبر په تاريخ کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10715, '2 Chronicles 14:1', '2 Chronicles', 14, 1, '&nbsp;ابياه بادشاه مړ شو او د داؤد د ښار په شاهى اديره کښې ښخ شو. د هغۀ زوئ آسا د هغۀ نه پس بادشاه جوړ شو، هغه وطن لس کاله د آسا د بادشاهۍ لاندې په امن کښې وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10716, '2 Chronicles 14:2', '2 Chronicles', 14, 2, '&nbsp;د آسا نه مالِک خُدائ د هغۀ خُدائ پاک خوشحاله وو، ځکه چې هغه کار يې کولو چې کوم ښۀ او صحيح وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10717, '2 Chronicles 14:3', '2 Chronicles', 14, 3, '&nbsp;هغۀ د پردو خلقو قربان‌ګاه او علاقائى عبادتخانې لرې کړې، د کاڼو پاکې ستنې يې ماتې کړې او د اشيرې د بُت نښې يې راوغورزولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10718, '2 Chronicles 14:4', '2 Chronicles', 14, 4, '&nbsp;هغۀ د يهوداه خلقو له حُکم ورکړو چې د مالِک خُدائ په مرضۍ کار کوى، کوم چې د هغوئ د پلار نيکۀ خُدائ پاک دے او د هغۀ حُکمونه او تعليمات منى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10719, '2 Chronicles 14:5', '2 Chronicles', 14, 5, '&nbsp;هغۀ د يهوداه د هر يو ښار نه علاقائى عبادتخانې د خوشبويۍ سوزولو ټولې قربان‌ګاه ختمې کړې، نو په دې وجه د هغۀ د بادشاهۍ لاندې حکومت په امن کښې وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10720, '2 Chronicles 14:6', '2 Chronicles', 14, 6, '&nbsp;هغۀ په خپل وخت کښې د يهوداه د ښارونو نه پاخۀ دېوالونه تاو کړل او تر ډېرې مودې پورې هلته جنګ نۀ وو، ځکه چې مالِک خُدائ هغۀ له امن ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10721, '2 Chronicles 14:7', '2 Chronicles', 14, 7, '&nbsp;هغۀ د يهوداه خلقو ته وفرمائيل، ”راځئ چې ښارونه د دېوالونو، برجونو، دروازو او سيخونو لګولو په ذريعه مضبوط کړُو. دا مُلک ځکه زمونږ په قابو کښې دے چې مونږ د مالِک خُدائ زمونږ د خُدائ پاک مرضى پوره کړې ده. هغۀ مونږ محفوظ کړى يُو او په هر لحاظ يې زمونږ حِفاظت کړے دے.“ نو هغوئ دا جوړ کړل او کامياب شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10722, '2 Chronicles 14:8', '2 Chronicles', 14, 8, '&nbsp;د آسا بادشاه سره د يهوداه قبيلې د درې لاکو سړو يو لښکر وو، چې د هغوئ سره ډالونه او نېزې وې، د بنيامين قبيلې نه ورسره د دوو لاکو او اتيا زره سړو، چې ډالونه او نېزې ورسره وې. دا ټول تکړه جنګيالى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10723, '2 Chronicles 14:9', '2 Chronicles', 14, 9, '&nbsp;د ايتهوپيا بادشاه زارح د لسو لاکو سړو د لښکر او د درېو سوو جنګى ګاډو سره په يهوداه حمله وکړه او د مريسه پورې وړاندې لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10724, '2 Chronicles 14:10', '2 Chronicles', 14, 10, '&nbsp;آسا د هغۀ سره د جنګ دپاره لاړو او د مريسه سره نزدې د صفاته په مېدان کښې يې دواړو طرفونو ته د جنګ دپاره صفونه جوړ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10725, '2 Chronicles 14:11', '2 Chronicles', 14, 11, '&nbsp;آسا مالِک خُدائ خپل خُدائ پاک ته سوال وکړو، ”اے مالِکه خُدايه، تۀ د تکړه لښکر په شان د يو کمزورى لښکر هم په آسانۍ سره مدد کولے شې. اے مالِکه خُدايه زمونږ خُدايه پاکه، اوس زمونږ مدد وکړه، ځکه چې مونږ په تا اعتماد کوُو او ستا په نوم د دې لوئ لښکر سره د جنګ دپاره راغلى يُو. مالِکه خُدايه، تۀ زمونږ خُدائ پاک يې، هيڅ څوک دا اُميد نۀ شى لرلے چې تا له شکست درکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10726, '2 Chronicles 14:12', '2 Chronicles', 14, 12, '&nbsp;کله چې د يهوداه لښکر او د آسا لښکر حمله وکړه نو مالِک خُدائ د ايتهوپيا لښکر له شکست ورکړو. نو د ايتهوپيا خلق وتښتېدل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10727, '2 Chronicles 14:13', '2 Chronicles', 14, 13, '&nbsp;او آسا او د هغۀ فوجيان تر جرار پورې په هغوئ پسې وُو. او دومره ډېر د ايتهوپيا خلق وژلے شوى وُو چې هغوئ د جنګ دپاره بيا نۀ شول راغونډېدلے. هغوئ د مالِک خُدائ او د هغۀ د لښکر نه شکست خوړلے وو او د يهوداه لښکر ډېر زيات مالِ غنيمت يوړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10728, '2 Chronicles 14:14', '2 Chronicles', 14, 14, '&nbsp;بيا هغوئ د جرار نه ګېرچاپېره علاقه کښې ښارونه تباه کړل، ځکه چې د هغه ځائ خلق د مالِک خُدائ نه سخت يرېدلى وُو. نو لښکر هغه ټول ښارونه لوټ کړل او ډېر زيات مالِ غنيمت يې يوړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10729, '2 Chronicles 14:15', '2 Chronicles', 14, 15, '&nbsp;هغوئ د شپانو په کېمپونو هم حمله وکړه او ډيرې زياتې ګډې او اوښان يې بوتلل. بيا هغوئ يروشلم ته راواپس شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10730, '2 Chronicles 15:1', '2 Chronicles', 15, 1, '&nbsp;د خُدائ پاک روح د عوبيد په زوئ عزرياه نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10731, '2 Chronicles 15:2', '2 Chronicles', 15, 2, '&nbsp;او هغه د آسا سره مِلاوېدو له لاړو. هغۀ ورته اوچت آواز وکړو، ”آسا بادشاه او د يهوداه او بنيامين ټولو خلقو، ما ته غوږ ونيسئ. مالِک خُدائ تاسو سره دے چې تر څو پورې تاسو د مالِک خُدائ سره يې. کۀ تاسو د هغۀ طلب وکړئ نو هغه به پېدا کړئ، خو کۀ تاسو ترې نه واوړئ، نو هغه به تاسو پرېږدى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10732, '2 Chronicles 15:3', '2 Chronicles', 15, 3, '&nbsp;تر ډېره وخته پورې اِسرائيل د حقيقى خُدائ پاک نه بغېر، د اِمامانو د ښودنې نه بغېر او بغېر د يو قانون نه ژوند تېرولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10733, '2 Chronicles 15:4', '2 Chronicles', 15, 4, '&nbsp;خو چې کله به مصيبت راغلو، نو هغوئ به مالِک خُدائ د بنى اِسرائيلو خُدائ پاک ته راوګرځېدل. هغوئ به د خُدائ پاک لټون وکړو او پېدا به يې کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10734, '2 Chronicles 15:5', '2 Chronicles', 15, 5, '&nbsp;په هغه ورځو کښې به هيڅ څوک په حِفاظت سره تلے راتلے نۀ شول، ځکه چې په هر مُلک کښې لويه ګډوډى وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10735, '2 Chronicles 15:6', '2 Chronicles', 15, 6, '&nbsp;يو قوم بل قوم خراب‌تُراب کړو او يو ښار بل ښار دړې وړې کړو، ځکه چې خُدائ پاک به په هغوئ باندې هر قسم مصيبت راوستلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10736, '2 Chronicles 15:7', '2 Chronicles', 15, 7, '&nbsp;خو تاسو تکړه شئ او بې‌حوصلې کېږئ مه، او بيا چې تاسو کوم کار کوئ نو د هغې به تاسو ته اِنعام ملاويږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10737, '2 Chronicles 15:8', '2 Chronicles', 15, 8, '&nbsp;کله چې آسا د هغه پېشګويۍ نه خبر شو چې د عوبيد زوئ عزرياه کړې وه، نو د هغۀ حوصله مضبوطه شوه. نو هغۀ د يهوداه او بنيامين په مُلک کښې او په هغه ښارونو کښې ټول پليت بُتان لرې کړل چې کوم ښارونه يې د اِفرائيم د غرونو په مُلک کښې قبضه کړى وُو. هغۀ د مالِک خُدائ هغه قربان‌ګاه هم بيا جوړه کړه کومه چې د مالِک خُدائ د کور په دربار کښې ولاړه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10738, '2 Chronicles 15:9', '2 Chronicles', 15, 9, '&nbsp;د اِفرائيم، منسى او د شمعون قبيلو ډېر خلق د آسا په طرف شوى وُو او د هغۀ په بادشاهۍ کښې اوسېدل، ځکه چې هغوئ ته پته لګېدلې وه چې مالِک خُدائ د هغۀ مل دے. آسا هغوئ ټول او د يهوداه او بنيامين خلق راوغوښتل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10739, '2 Chronicles 15:10', '2 Chronicles', 15, 10, '&nbsp;نو هغوئ د آسا د بادشاهۍ په پينځلسم کال په درېمه مياشت په يروشلم کښې راغونډ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10740, '2 Chronicles 15:11', '2 Chronicles', 15, 11, '&nbsp;په هغه ورځ هغوئ د هغه مالِ غنيمت نه مالِک خُدائ ته نذرانې پېش کړې چې کوم هغوئ قبضه کړے وو، اووۀ سوه څاروى او اووۀ زره ګډان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10741, '2 Chronicles 15:12', '2 Chronicles', 15, 12, '&nbsp;هغوئ يو لوظ وکړو چې هغوئ به د زړۀ د اخلاصه د مالِک خُدائ د خپل پلار نيکۀ د خُدائ پاک عبادت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10742, '2 Chronicles 15:13', '2 Chronicles', 15, 13, '&nbsp;چې هر يو نر يا ښځې، ځوان يا بوډا به د هغۀ عبادت نۀ کولو نو هغه به وژلے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10743, '2 Chronicles 15:14', '2 Chronicles', 15, 14, '&nbsp;نو هغوئ د مالِک خُدائ په نوم په اوچت آواز سره قسم وکړو چې هغوئ به دا لوظ پوره کوى او بيا هغوئ چغه ووهله او بيګلې يې وغږولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10744, '2 Chronicles 15:15', '2 Chronicles', 15, 15, '&nbsp;د يهوداه ټول خلق خوشحاله وُو ځکه چې هغوئ د زړۀ د اخلاصه لوظ کړے وو. هغوئ د مالِک خُدائ په عبادت کښې خوشحاله وُو، مالِک خُدائ هغوئ قبول کړل او د ټولو دشمنانو نه يې په امن کښې کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10745, '2 Chronicles 15:16', '2 Chronicles', 15, 16, '&nbsp;آسا بادشاه خپله نيا معکه د مور مَلِکې د عُهدې نه لرې کړه، ځکه چې هغې د اشيرې د بې‌شرمۍ بُت جوړ کړے وو. آسا دا بُت مات کړو، ټوټې ټوټې يې کړو او د دې ټوټې يې د قِدرون په وادۍ کښې وسوزولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10746, '2 Chronicles 15:17', '2 Chronicles', 15, 17, '&nbsp;اګر چې آسا بيا هم په هغه مُلک کښې علاقائى عبادتخانې تباه نۀ کړې، خو هغه ټول عُمر د مالِک خُدائ وفادار پاتې شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10747, '2 Chronicles 15:18', '2 Chronicles', 15, 18, '&nbsp;هغۀ د مالِک خُدائ په کور کښې هغه ټول څيزونه کېښودل کوم چې د هغۀ پلار ابياه خُدائ پاک ته وقف کړى وُو او داسې د سرو زرو او سپينو زرو هغه څيزونه يې هم کېښودل چې کوم هغۀ په خپله وقف کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10748, '2 Chronicles 15:19', '2 Chronicles', 15, 19, '&nbsp;د هغۀ د بادشاهۍ تر پينځۀ دېرشم کال پورې نور جنګونه نۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10749, '2 Chronicles 16:1', '2 Chronicles', 16, 1, '&nbsp;د آسا د بادشاهۍ په شپږ دېرشم کال، د اِسرائيل بادشاه بعشا په يهوداه حمله وکړه او د راما نه يې د پَخو دېوالونو تاوول شروع کړل دا دې دپاره چې د يهوداه بادشاه آسا د علاقې نه د ټولو خلقو تګ راتګ بند کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10750, '2 Chronicles 16:2', '2 Chronicles', 16, 2, '&nbsp;نو آسا د محل او د مالِک خُدائ د کور د خزانې نه سرۀ زر او سپين زر واخستل او د دې پېغام سره يې د شام بادشاه بِن‌حدد له دمشق ته ولېږل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10751, '2 Chronicles 16:3', '2 Chronicles', 16, 3, '&nbsp;”راځئ چې زمونږ د پلار نيکۀ په شان په خپلو کښې ملګرى شُو. ګوره، زۀ تا له سرۀ زر او سپين زر درلېږم. اوس د اِسرائيل بادشاه بعشا سره خپل اِتحاد مات کړه نو داسې به هغه زما د علاقې نه خپل فوجيان وباسى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10752, '2 Chronicles 16:4', '2 Chronicles', 16, 4, '&nbsp;بِن‌حدد د آسا دا مشوره ومنله او خپل فوجى آفسران او خپل فوجيان يې ولېږل چې د اِسرائيل په ښارونو حمله وکړى. هغوئ عيون، دان، ابيل‌بيت‌معکه او د نفتالى هغه ټول ښارونه قبضه کړل چرته چې سامانونه جمع کولے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10753, '2 Chronicles 16:5', '2 Chronicles', 16, 5, '&nbsp;کله چې بعشا بادشاه خبر شو چې څۀ شوى وُو، نو هغۀ د راما نه پاخۀ دېوالونه جوړول بند کړل او کار يې پرېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10754, '2 Chronicles 16:6', '2 Chronicles', 16, 6, '&nbsp;بيا آسا بادشاه د ټول يهوداه نه سړى راغونډ کړل او هغوئ له يې حُکم ورکړو چې هغه کاڼى او لرګى راوړئ چې کوم بعشا په راما کښې استعمالول او هغوئ دا د جبعه او د مصفاه ښارونو نه د پَخو دېوالونو تاوولو دپاره استعمال کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10755, '2 Chronicles 16:7', '2 Chronicles', 16, 7, '&nbsp;په هغه وخت کښې حنانى پېغمبر آسا بادشاه له لاړو او ورته يې وفرمائيل، ”د مالِک خُدائ ستا د خُدائ پاک په ځائ تا د شام په بادشاه بهروسه وکړه، نو په دې وجه د شام د بادشاه لښکر ستا نه خلاص شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10756, '2 Chronicles 16:8', '2 Chronicles', 16, 8, '&nbsp;د ايتهوپيا او د ليبيا د خلقو سره ډېر فوجيان او ډېرې جنګى ګاډۍ او په آسونو سوارۀ کسان نۀ وُو څۀ؟ خو تا په مالِک خُدائ بهروسه وکړه نو ځکه هغۀ تا له په هغوئ باندې فتح درکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10757, '2 Chronicles 16:9', '2 Chronicles', 16, 9, '&nbsp;مالِک خُدائ په ټوله دُنيا د دې دپاره نظر اچوى چې هغه کسانو له طاقت ورکړى چې د چا زړۀ د اخلاصه د هغۀ وفادار وى. تۀ څومره کم عقل يې. د اوس نه به تۀ په جنګ کښې راګېر يې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10758, '2 Chronicles 16:10', '2 Chronicles', 16, 10, '&nbsp;په دې باندې آسا هغه پېغمبر ته دومره غصه شو چې هغه يې په زنځيرونو وتړلو او قېد يې کړو. هم د هغه وخت نه آسا د خلقو سره ظلم زياتے شروع کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10759, '2 Chronicles 16:11', '2 Chronicles', 16, 11, '&nbsp;د اول نه واخله تر آخره پورې د آسا د بادشاهۍ ټولې واقعې د اِسرائيل او يهوداه بادشاهانو په تاريخ کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10760, '2 Chronicles 16:12', '2 Chronicles', 16, 12, '&nbsp;د خپلې بادشاهۍ په يو کم څلوېښتم کال آسا د پښو د يو سخت مرض په وجه شل شو، خو بيا هم هغه مالِک خُدائ ته د مدد دپاره ور ونۀ ګرځېدو او صرف طبيبانو له لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10761, '2 Chronicles 16:13', '2 Chronicles', 16, 13, '&nbsp;دوه کاله وروستو هغه مړ شو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10762, '2 Chronicles 16:14', '2 Chronicles', 16, 14, '&nbsp;او هغه په هغه قبر کښې ښخ شو کوم چې هغۀ د داؤد په ښار کښې په يو غټ ګټ کښې خپل ځان دپاره جوړ کړے وو. هغوئ د هغۀ ښخولو دپاره مصالحې او خوشبويۍ والا تېل استعمال کړل او هغوئ د هغۀ په مرګ باندې د غم دپاره يو لوئ اور بل کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10763, '2 Chronicles 17:1', '2 Chronicles', 17, 1, '&nbsp;يهوسفط د خپل پلار آسا نه پس بادشاه جوړ شو او د اِسرائيل خِلاف يې خپل ځان مضبوط کړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10764, '2 Chronicles 17:2', '2 Chronicles', 17, 2, '&nbsp;هغۀ د يهوداه د پَخو دېوالونو په ښارونو کښې، د يهوداه په مُلک کښې او د اِفرائيم د علاقې په هغه ښارونو کښې کوم چې آسا قبضه کړى وُو، فوجيان مقرر کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10765, '2 Chronicles 17:3', '2 Chronicles', 17, 3, '&nbsp;مالِک خُدائ د يهوسفط مل وو ځکه چې هغه د خپل پلار په هغه نقش قدم باندې روان وو لکه څنګه چې داؤد د بادشاهۍ په شروع کښې ښۀ وو او يهوسفط د بعل عبادت ونۀ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10766, '2 Chronicles 17:4', '2 Chronicles', 17, 4, '&nbsp;هغۀ د خپل پلار د خُدائ پاک خِدمت کولو او د خُدائ پاک حُکمونه يې منل او هغه شان عمل يې نۀ کولو څنګه چې د اِسرائيل بادشاهانو کول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10767, '2 Chronicles 17:5', '2 Chronicles', 17, 5, '&nbsp;مالِک خُدائ د يهوداه په بادشاهۍ باندې د يهوسفط قابو مضبوطه کړه او ټولو خلقو به هغۀ له تُحفې راوړلې، نو داسې هغه مالداره او ډېر عزتمند شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10768, '2 Chronicles 17:6', '2 Chronicles', 17, 6, '&nbsp;هغۀ خپل ځان د مالِک خُدائ کار ته وقف کړے وو او علاقائى عبادتخانې او د اشيرې بُت نښې يې په يهوداه کښې تباه کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10769, '2 Chronicles 17:7', '2 Chronicles', 17, 7, '&nbsp;هغۀ د خپلې بادشاهۍ په درېم کال دا آفسران ولېږل چې د يهوداه په ښارونو کښې تعليم ورکړى، بِن‌خېل، عبدياه، زکرياه، نتنى‌ايل او ميکاياه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10770, '2 Chronicles 17:8', '2 Chronicles', 17, 8, '&nbsp;د هغوئ سره نهۀ ليويان او دوه اِمامان ملګرى وُو. ليويان دا وُو، سمعياه، نتنياه، زبدياه، عساهيل، سميراموت، يونتن، ادونياه، طوبياه او طوب ادونياه، او اليسمع او يهورام اِمامان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10771, '2 Chronicles 17:9', '2 Chronicles', 17, 9, '&nbsp;هغوئ د مالِک خُدائ د تورات کِتاب واخستلو او د يهوداه ټولو ښارونو ته لاړل او خلقو له يې تعليم ورکولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10772, '2 Chronicles 17:10', '2 Chronicles', 17, 10, '&nbsp;په ګېرچاپېره حکومتونو باندې د مالِک خُدائ يره راغله نو هغوئ د يهوسفط خِلاف جنګ نۀ شو کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10773, '2 Chronicles 17:11', '2 Chronicles', 17, 11, '&nbsp;څۀ فلستيانو يهوسفط له په يو لوئ مِقدار کښې سپين زر او نورې تُحفې راوړې او څۀ عربو ورله اووۀ زره او اووۀ سوه ګډان او اووۀ زره او اووۀ سوه چېلۍ راوستلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10774, '2 Chronicles 17:12', '2 Chronicles', 17, 12, '&nbsp;نو يهوسفط نوره هم ترقى کوله او تکړه کېدو. هغۀ په يهوداه کښې ځائ په ځائ قلعې او د ښارونو ګودامونه جوړ کړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10775, '2 Chronicles 17:13', '2 Chronicles', 17, 13, '&nbsp;چرته چې په لوئ مِقدار کښې د هغوئ سامانونه جمع شوى وُو. هغۀ په يروشلم کښې تکړه آفسران مقرر کړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10776, '2 Chronicles 17:14', '2 Chronicles', 17, 14, '&nbsp;د هغۀ لښکر د قبيلو په مطابق جوړ شوے وو. عدنه د يهوداه د ډلو د فوجيانو مشر وو او درې لاکه فوجيان د هغۀ د واک اختيار لاندې وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10777, '2 Chronicles 17:15', '2 Chronicles', 17, 15, '&nbsp;يهوحنان په هغۀ پسې دوېم کس وو، چې د هغۀ سره دوه لاکه او اتيا زره فوجيان وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10778, '2 Chronicles 17:16', '2 Chronicles', 17, 16, '&nbsp;درېم د زِکرى زوئ عمسياه وو، چې د هغۀ سره دوه لاکه فوجيان وُو. او عمسياه به په رضاکارانه توګه د مالِک خُدائ خِدمت کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10779, '2 Chronicles 17:17', '2 Chronicles', 17, 17, '&nbsp;د بنيامين د ډلو د فوجيانو مشر اليدع وو، چې هغه يو ډېر تکړه فوجى وو، هغه د دوو لاکو فوجيانو مشر وو چې ډالونه او ليندې ورسره وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10780, '2 Chronicles 17:18', '2 Chronicles', 17, 18, '&nbsp;په هغۀ پسې دوېم مشر يهوزبد وو چې د هغۀ سره يو سل او اتيا زره سړى وُو، چې ښۀ جنګى سامان ورسره وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10781, '2 Chronicles 17:19', '2 Chronicles', 17, 19, '&nbsp;دې سړو په يروشلم کښې د بادشاه خِدمت کولو او د دې نه علاوه هغۀ د يهوداه د پَخو دېوالونو په ښارونو کښې نور فوجيان هم مقرر کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10782, '2 Chronicles 18:1', '2 Chronicles', 18, 1, '&nbsp;نو يهوسفط ډېر دولتمند او عزتمند شو او يهوسفط خپل زوئ ته د اخى‌اب لور وادۀ کړه نو داسې هغه د اخى‌اب ملګرے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10783, '2 Chronicles 18:2', '2 Chronicles', 18, 2, '&nbsp;يو څو کاله وروستو يهوسفط د اخى‌اب سره مِلاوېدو دپاره د سامريه ښار ته لاړو. د يهوسفط او د هغۀ د کسانو په درناوى کښې اخى‌اب د يوې مېلمستيا په توګه ډېر ګډان او څاروى حلال کړل. هغۀ يهوسفط دې ته جوړولو چې په رامات‌جِلعاد ښار باندې دواړه په يو ځائ باندې حمله وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10784, '2 Chronicles 18:3', '2 Chronicles', 18, 3, '&nbsp;هغۀ ورنه تپوس وکړو، ”تۀ به رامات‌جِلعاد باندې د حملې کولو دپاره ما سره لاړ شې؟“ يهوسفط جواب ورکړو، ”کله چې تۀ تيار شې نو زۀ او زما فوج تيار يُو. مونږ به تا سره ملګرى شُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10785, '2 Chronicles 18:4', '2 Chronicles', 18, 4, '&nbsp;بيا هغۀ بادشاه ته دا هم ووئيل، ”خو اول لږه د مالِک خُدائ سره مشوره وکړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10786, '2 Chronicles 18:5', '2 Chronicles', 18, 5, '&nbsp;نو اخى‌اب پېغمبران راوغوښتل چې تقريباً څلور سوه وُو او د هغوئ نه يې تپوس وکړو، ”ما له رامات‌جِلعاد ته تلل په کار دى او کۀ نه؟“ هغوئ ورته وفرمائيل، ”حمله پرې وکړه، خُدائ پاک به تا له فتح درکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10787, '2 Chronicles 18:6', '2 Chronicles', 18, 6, '&nbsp;خو يهوسفط ترې نه تپوس وکړو، ”داسې يو بل پېغمبر نشته څۀ چې د هغۀ په ذريعه مونږ د مالِک خُدائ سره مشوره وکړُو؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10788, '2 Chronicles 18:7', '2 Chronicles', 18, 7, '&nbsp;اخى‌اب ورته ووئيل، ”يو بل پېغمبر هم شته دے چې د اِمله زوئ ميکاياه دے. خو زۀ د هغۀ نه نفرت کوم ځکه چې هغۀ هيڅکله زما دپاره ښۀ پېشګوئې نۀ ده کړې، هغه همېشه بده پېشګوئې کوى.“ يهوسفط ورته ووئيل، ”تا له داسې وئيل نۀ دى په کار.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10789, '2 Chronicles 18:8', '2 Chronicles', 18, 8, '&nbsp;نو اخى‌اب بادشاه د دربار يو آفسر راوغوښتو او ورته يې ووئيل چې لاړ شه او سمدستى ميکاياه راوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10790, '2 Chronicles 18:9', '2 Chronicles', 18, 9, '&nbsp;هغه دوه بادشاهان د سامريه د دروازې نه لږ بهر په درمند کښې په خپلو تختُونو باندې ناست وُو چې خپلې شاهى چُوغې يې اغوستې وې او ټولو پېغمبرانو د هغوئ په مخکښې پېشګويانې ورکولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10791, '2 Chronicles 18:10', '2 Chronicles', 18, 10, '&nbsp;د هغوئ نه يو پېغمبر د کنعانه زوئ صدقياه د اوسپنې ښکر جوړ کړى وُو او اخى‌اب ته يې وفرمائيل، ”مالِک خُدائ داسې فرمائى چې په دې ښکرونو به د شام خلق وهى چې برباد شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10792, '2 Chronicles 18:11', '2 Chronicles', 18, 11, '&nbsp;نورو ټولو پېغمبرانو هم دغه شان وفرمائيل. هغوئ وفرمائيل، ”د رامات‌جِلعاد خِلاف روان شه او تۀ به فتح ومومې، مالِک خُدائ به تا له فتح درکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10793, '2 Chronicles 18:12', '2 Chronicles', 18, 12, '&nbsp;په دې دوران کښې کوم آفسر چې د ميکاياه د راوستو دپاره تلے وو نو هغۀ ورته ووئيل، ”ټولو پېغمبرانو د بادشاه د کاميابۍ پېشګوئې ورکړې ده، نو ستا دپاره به ښۀ وى چې تۀ هم داسې وکړې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10794, '2 Chronicles 18:13', '2 Chronicles', 18, 13, '&nbsp;خو ميکاياه ورته وفرمائيل، ”زۀ د ژوندى مالِک خُدائ په نوم قسم کوم چې زۀ به هم هغه څۀ وايم چې څۀ ما ته خُدائ پاک فرمائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10795, '2 Chronicles 18:14', '2 Chronicles', 18, 14, '&nbsp;کله چې هغه د اخى‌اب په مخکښې حاضر شو نو بادشاه ترې نه تپوس وکړو، ”ميکاياه، يهوسفط بادشاه او زۀ په رامات‌جِلعاد باندې د حملې کولو دپاره لاړ شُو او کۀ نه؟“ نو هغۀ جواب ورکړو، ”آو، حمله پرې وکړه، تۀ به کامياب شې، هغوئ به ستا د واک اختيار لاندې راشى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10796, '2 Chronicles 18:15', '2 Chronicles', 18, 15, '&nbsp;خو اخى‌اب ورته ووئيل، ”کله چې تۀ ما سره د مالِک خُدائ په نوم خبرې کوې نو رښتيا رښتيا وايه. دا به زۀ تا ته څو ځلې وايم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10797, '2 Chronicles 18:16', '2 Chronicles', 18, 16, '&nbsp;ميکاياه ورته وفرمائيل، ”زۀ د اِسرائيل لښکر ګورم چې په غرونو باندې داسې خور دے لکه چې د شپون نه بغېر ګډې خورې ورې وى. او مالِک خُدائ وفرمائيل چې د دې سړو مشر نشته، نو هغوئ پرېږده چې په خېر سره کورونو ته لاړ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10798, '2 Chronicles 18:17', '2 Chronicles', 18, 17, '&nbsp;اخى‌اب يهوسفط ته ووئيل، ”ما تا ته وئيلى دى چې هغۀ زما دپاره هيڅکله هم ښۀ پېشګوئې نۀ ده کړې، هغه همېشه بده پېشګوئې کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10799, '2 Chronicles 18:18', '2 Chronicles', 18, 18, '&nbsp;ميکاياه دا هم وفرمائيل چې، ”اوس چې څۀ مالِک خُدائ فرمائى نو هغې ته غوږ ونيسئ. ما وليدل چې مالِک خُدائ په آسمان کښې په خپل تخت باندې ناست دے او د هغۀ ټولې فرښتې د هغۀ يو طرف او بل طرف ته ولاړې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10800, '2 Chronicles 18:19', '2 Chronicles', 18, 19, '&nbsp;مالِک خُدائ تپوس وکړو چې اخى‌اب به څوک دوکه کړى چې هغه لاړ شى او په رامات‌جِلعاد کښې ووژلے شى؟ نو څۀ فرښتو يو څۀ وفرمائيل او هغه نورو بل څۀ وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');